:root {
  --bg: #1e293b;
  --card-bg: #334155;
  --text: #f1f5f9;
  --accent: #38bdf8;
  --success: #4ade80;
  --danger: #f87171;
  --waiting: #64748b;
  --radius: 12px;
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
}

body {
  font-family: var(--font);
  font-size: 18px;
  line-height: 1.5;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.card {
  background: var(--card-bg);
  border-radius: var(--radius);
  padding: 32px 24px;
  max-width: 480px;
  width: 100%;
  text-align: center;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
}

h1 {
  font-size: 1.6rem;
  margin-bottom: 8px;
  color: var(--accent);
}

.instructions {
  font-size: 0.95rem;
  color: #cbd5e1;
  margin-bottom: 24px;
}

.box {
  width: 100%;
  aspect-ratio: 1 / 1;
  max-height: 240px;
  border-radius: var(--radius);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.3rem;
  font-weight: 700;
  cursor: pointer;
  user-select: none;
  transition: background-color 0.15s ease, transform 0.1s ease;
  margin-bottom: 24px;
  border: 3px solid transparent;
}

.box.waiting {
  background: var(--waiting);
  color: #e2e8f0;
}

.box.ready {
  background: var(--success);
  color: #052e16;
}

.box.too-soon {
  background: var(--danger);
  color: #450a0a;
}

.box:hover {
  transform: scale(1.02);
}

.box:active {
  transform: scale(0.98);
}

.box:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 4px;
}

.controls {
  display: flex;
  gap: 12px;
  justify-content: center;
  flex-wrap: wrap;
  margin-bottom: 16px;
}

.btn {
  font-family: inherit;
  font-size: 1rem;
  font-weight: 600;
  padding: 12px 24px;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  transition: background-color 0.15s ease, transform 0.1s ease, box-shadow 0.15s ease;
}

.btn.primary {
  background: var(--accent);
  color: #082f49;
}

.btn.primary:hover {
  background: #7dd3fc;
}

.btn.primary:active {
  transform: scale(0.97);
  background: #0ea5e9;
}

.btn.secondary {
  background: #475569;
  color: var(--text);
}

.btn.secondary:hover {
  background: #64748b;
}

.btn.secondary:active {
  transform: scale(0.97);
  background: #334155;
}

.btn:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
  transform: none;
}

.result {
  font-size: 1.1rem;
  font-weight: 600;
  min-height: 1.6em;
  margin-bottom: 8px;
}

.result.success {
  color: var(--success);
}

.result.error {
  color: var(--danger);
}

.best {
  font-size: 0.95rem;
  color: #94a3b8;
}

@media (max-width: 400px) {
  .card {
    padding: 24px 16px;
  }
  h1 {
    font-size: 1.4rem;
  }
  .box {
    font-size: 1.1rem;
  }
  .btn {
    padding: 10px 18px;
    font-size: 0.95rem;
  }
}

(function () {
  'use strict';

  const box = document.getElementById('reaction-box');
  const boxText = document.getElementById('box-text');
  const startBtn = document.getElementById('start-btn');
  const resetBtn = document.getElementById('reset-btn');
  const resultEl = document.getElementById('result');
  const bestEl = document.getElementById('best');

  let state = 'idle'; // idle | waiting | ready | result
  let timeoutId = null;
  let startTime = 0;
  let bestTime = null;

  try {
    const stored = localStorage.getItem('reactionBest');
    if (stored !== null) {
      bestTime = parseInt(stored, 10);
      if (isNaN(bestTime)) bestTime = null;
    }
  } catch (e) {
    // localStorage unavailable
  }

  function updateBestDisplay() {
    if (bestTime !== null) {
      bestEl.textContent = 'Best: ' + bestTime + ' ms';
    } else {
      bestEl.textContent = 'Best: —';
    }
  }

  function saveBest(time) {
    if (bestTime === null || time < bestTime) {
      bestTime = time;
      try {
        localStorage.setItem('reactionBest', String(bestTime));
      } catch (e) {
        // ignore
      }
      updateBestDisplay();
    }
  }

  function setState(newState) {
    state = newState;
    box.className = 'box ' + newState;
    if (newState === 'waiting') {
      boxText.textContent = 'Wait for green…';
      box.setAttribute('aria-label', 'Waiting for green. Do not click yet.');
      startBtn.disabled = true;
    } else if (newState === 'ready') {
      boxText.textContent = 'Click!';
      box.setAttribute('aria-label', 'Green box. Click now!');
      startBtn.disabled = true;
    } else if (newState === 'idle') {
      boxText.textContent = 'Click Start';
      box.setAttribute('aria-label', 'Reaction box. Press Start to begin.');
      startBtn.disabled = false;
    } else if (newState === 'result') {
      startBtn.disabled = false;
    }
  }

  function startTest() {
    if (state === 'waiting' || state === 'ready') return;
    clearTimeout(timeoutId);
    resultEl.textContent = '';
    resultEl.className = 'result';
    setState('waiting');
    const delay = 1000 + Math.random() * 4000; // 1–5 seconds
    timeoutId = setTimeout(function () {
      startTime = performance.now();
      setState('ready');
    }, delay);
  }

  function handleBoxClick() {
    if (state === 'idle' || state === 'result') {
      startTest();
      return;
    }
    if (state === 'waiting') {
      clearTimeout(timeoutId);
      setState('idle');
      resultEl.textContent = 'Too soon!';
      resultEl.className = 'result error';
      return;
    }
    if (state === 'ready') {
      const reaction = Math.round(performance.now() - startTime);
      setState('result');
      resultEl.textContent = reaction + ' ms';
      resultEl.className = 'result success';
      boxText.textContent = reaction + ' ms';
      box.setAttribute('aria-label', 'Your time: ' + reaction + ' milliseconds. Press Start to try again.');
      saveBest(reaction);
    }
  }

  box.addEventListener('click', handleBoxClick);
  box.addEventListener('keydown', function (e) {
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      handleBoxClick();
    }
  });

  startBtn.addEventListener('click', startTest);

  resetBtn.addEventListener('click', function () {
    bestTime = null;
    try {
      localStorage.removeItem('reactionBest');
    } catch (e) {
      // ignore
    }
    updateBestDisplay();
  });

  updateBestDisplay();
})();
